/// <summary>
/// Business event triggered when a sales return order is created.
/// </summary>
[BusinessEvents(classStr(AAXSalesReturnOrderCreatedBusinessEventContract), 'SalesReturnOrderCreatedBusinessEventName', 'SalesReturnOrderCreatedBusinessEventDescription', ModuleAxapta::SalesOrder)]
public final class AAXSalesReturnOrderCreatedBusinessEvent extends BusinessEventsBase
{
    private SalesTable salesTable;

}

Method.Source:
/// <summary>
/// Gets or sets the source SalesTable for building the event contract.
/// </summary>
private SalesTable parmSalesTable(SalesTable _salesTable = salesTable)
{
    salesTable = _salesTable;

    return salesTable;
}

/// <summary>
/// Creates a new <c>AAXSalesReturnOrderCreatedBusinessEvent</c> instance from the specified <c>SalesTable</c> record.
/// </summary>
/// <param name="_salesTable">The source SalesTable record.</param>
/// <returns>A new instance of <c>AAXSalesReturnOrderCreatedBusinessEvent</c>.</returns>
public static AAXSalesReturnOrderCreatedBusinessEvent newFromSalesTable(SalesTable _salesTable)
{
    AAXSalesReturnOrderCreatedBusinessEvent businessEvent = new AAXSalesReturnOrderCreatedBusinessEvent();
    businessEvent.parmSalesTable(_salesTable);

    return businessEvent;
}

/// <summary>
/// Private constructor. Use static factory methods to create instances.
/// </summary>
private void new()
{
}

/// <summary>
/// Builds the data contract for this business event.
/// </summary>
/// <returns>The populated <c>AAXSalesReturnOrderCreatedBusinessEventContract</c>.</returns>
[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    return AAXSalesReturnOrderCreatedBusinessEventContract::newFromSalesTable(salesTable);
}
